namespace Alto\Image\Test;

/**
 * Provides a real camera EXIF segment for conformance fixtures.
 *
 * @internal
 *
 * Source: https://commons.wikimedia.org/wiki/File:Angela_Merkel_IMG_4162_edit.jpg
 * Author: Christoph Braun
 * Device: Canon EOS 5D Mark II
 * License: CC0-1.0
 * SHA-256: 69cc8c01861d85e6d5ca2a044bb3e0470b174206a8724fbaccd28b44b7dfc70a
 *
 * @author Simon André <smn.andre@gmail.com>
 */
final class DeviceExif
{
    private const string SEGMENT = '';

    public static function segment(): string
    {
        $segment = base64_decode(self::SEGMENT, true);

        // @codeCoverageIgnoreStart
        if (false === $segment) {
            throw new \RuntimeException('The embedded device EXIF segment is not valid base64.');
        }
        // @codeCoverageIgnoreEnd

        return $segment;
    }
}
